@font-face{font-family:Open Sans;src:url('assets/fonts/open-sans-latin.woff2') format('woff2');font-weight:400 600;font-display:swap}
:root{color-scheme:light;--paper:#faf9f6;--ink:#292822;--muted:#747168;--line:#dedbd2;--accent:#8b443e;--serif:'Spectral',Georgia,serif;--sans:'Open Sans',Arial,sans-serif}
*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:40px}body{margin:0;background:var(--paper);color:var(--ink);font-family:var(--serif);font-size:18px;line-height:1.75}::selection{background:#ebd8c8}a{color:inherit;text-underline-offset:5px;text-decoration-style:dotted}a:hover{color:var(--accent);text-decoration-style:solid}a:focus-visible{outline:2px solid var(--accent);outline-offset:5px}img{max-width:100%;height:auto;display:block}figure{margin:0}p{margin:0 0 1.25em}code{font: .79em ui-monospace,SFMono-Regular,Consolas,monospace;background:#eeece6;padding:.12em .3em;overflow-wrap:anywhere}.site-header{max-width:1320px;margin:auto;padding:32px 48px;display:flex;justify-content:space-between;gap:28px;align-items:center;font:14px var(--sans)}.site-header a{text-decoration:none}.wordmark{font-weight:600}.wordmark span{font-weight:400;color:var(--muted)}.site-header nav{display:flex;gap:34px}.masthead{max-width:1080px;margin:72px auto 48px;padding:0 32px}.eyebrow,.section-label,.contents>p{font:11px/1.6 var(--sans);letter-spacing:.16em;color:var(--muted)}h1{font:500 clamp(64px,7vw,104px)/1.03 'EB Garamond',Georgia,serif;letter-spacing:-.045em;margin:20px 0 16px}.dek{font:italic 25px/1.5 var(--serif);color:#71685f;margin:0 0 30px}.byline{display:flex;gap:8px 28px;flex-wrap:wrap;font:12px/1.6 var(--sans);color:var(--muted)}.hero{max-width:1120px;margin:0 auto 100px;padding:0 32px}.hero-images{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;align-items:center;background:#eeece6;padding:12px}.hero img{width:100%}.hero figcaption{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;text-align:center;font:11px/1.5 var(--sans);letter-spacing:.07em;color:var(--muted);padding:14px 12px}.reading-layout{display:grid;grid-template-columns:190px minmax(0,800px);gap:56px;max-width:1150px;padding:0 32px;margin:0 auto}.contents{position:sticky;top:35px;align-self:start}.contents nav{display:flex;flex-direction:column;gap:14px}.contents nav a{font:12px/1.6 var(--sans);display:flex;gap:12px;text-decoration:none;color:var(--muted)}.contents nav a:hover{color:var(--accent)}.contents nav span{font:12px/1.6 Georgia,serif;color:#a5a095;width:18px;flex-shrink:0}.contents .back-top{display:inline-block;margin-top:30px;padding-top:20px;border-top:1px solid var(--line);font:11px var(--sans);color:var(--muted)}article{min-width:0}section{margin-bottom:100px}h2{font:500 34px/1.25 var(--serif);letter-spacing:-.025em;margin:10px 0 32px;padding-bottom:24px;border-bottom:1px solid var(--line)}section>p{max-width:730px}.figure-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:28px 18px;margin:38px 0 40px}.figure-grid figure{min-width:0}.image-link{display:block;background:#eeeae2}.image-link img{width:100%;transition:opacity .15s}.image-link:hover img{opacity:.92}figcaption{font:12px/1.6 var(--sans);color:var(--muted);padding:12px 3px 0;text-align:left}.table-scroll{overflow-x:auto;margin:35px 0}.measurements{width:100%;border-collapse:collapse;font:12px/1.6 var(--sans);text-align:right;font-variant-numeric:tabular-nums}.measurements th{font-weight:600;color:var(--muted);padding:14px 12px;border-top:1px solid var(--line);border-bottom:1px solid var(--line)}.measurements td{padding:15px 12px;border-bottom:1px solid #e9e6df}.measurements th:first-child,.measurements td:first-child{text-align:left}#acknowledgements{font-size:16px;color:var(--muted)}#acknowledgements h2{color:var(--ink)}.site-footer{max-width:1086px;margin:0 auto;padding:30px 0 45px;border-top:1px solid var(--line);display:flex;justify-content:space-between;gap:20px;font:12px var(--sans);color:var(--muted)}.skip-link{position:absolute;left:12px;top:-100px;background:white;padding:8px;z-index:5}.skip-link:focus{top:12px}
@media(max-width:1000px){.reading-layout{grid-template-columns:150px minmax(0,1fr);gap:30px}.site-footer{margin:0 32px}.wordmark span{display:none}.masthead{margin-top:55px}}
@media(max-width:760px){body{font-size:17px;line-height:1.7}.site-header{padding:25px 22px;font-size:12px}.site-header nav{gap:18px}.masthead{margin:40px 0 30px;padding:0 22px}h1{font-size:66px}.dek{font-size:21px}.byline{font-size:11px;gap:8px 18px}.hero{padding:0 16px;margin-bottom:40px}.hero-images{gap:6px;padding:6px}.hero figcaption{font-size:9px;padding:10px 0}.reading-layout{display:block;padding:0 22px}.contents{position:static;border-top:1px solid var(--line);border-bottom:1px solid var(--line);padding:20px 0;margin-bottom:55px}.contents nav{display:grid;grid-template-columns:1fr 1fr;gap:12px}.contents .back-top{display:none}h2{font-size:29px;margin-bottom:25px}.figure-grid{gap:22px 12px;margin:28px 0}figcaption{font-size:11px}section{margin-bottom:65px}.site-footer{margin:0 22px;font-size:10px}.measurements{font-size:11px}.measurements td,.measurements th{padding:10px 8px}}
@media(max-width:420px){.figure-grid{grid-template-columns:1fr}.site-header nav{gap:12px}.site-header{font-size:11px}.hero figcaption{letter-spacing:0}.contents nav a{font-size:11px}}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}*{transition:none!important}}
@media print{@page{margin:16mm}body{background:white;font-size:11pt;line-height:1.5}.site-header,.contents,.skip-link,.site-footer{display:none}.masthead{margin:0 0 20px;padding:0}h1{font-size:48pt}.dek{font-size:16pt}.hero{padding:0;margin-bottom:30px}.reading-layout{display:block;padding:0;max-width:none}section{margin-bottom:30px}h2{font-size:23pt;break-after:avoid}.figure-grid{gap:20px 12px;margin:20px 0}.figure-grid figure{break-inside:avoid}figcaption{font-size:9pt}.table-scroll{overflow:visible}tr{break-inside:avoid}a{color:inherit}p{orphans:3;widows:3}}

/* Academic typography and mathematical notation. */
@font-face{font-family:Latin Modern;font-style:normal;font-weight:400;font-display:swap;src:url("assets/fonts/latin-modern-400-normal.woff2") format("woff2"),url(data:font/woff;base64,) format("woff"),url(data:font/ttf;base64,) format("truetype")}
@font-face{font-family:Latin Modern;font-style:italic;font-weight:400;font-display:swap;src:url("assets/fonts/latin-modern-400-italic.woff2") format("woff2"),url(data:font/woff;base64,) format("woff"),url(data:font/ttf;base64,) format("truetype")}
@font-face{font-family:Latin Modern;font-style:normal;font-weight:700;font-display:swap;src:url("assets/fonts/latin-modern-700-normal.woff2") format("woff2"),url(data:font/woff;base64,) format("woff"),url(data:font/ttf;base64,) format("truetype")}
@font-face{font-family:Latin Modern;font-style:italic;font-weight:700;font-display:swap;src:url("assets/fonts/latin-modern-700-italic.woff2") format("woff2"),url(data:font/woff;base64,) format("woff"),url(data:font/ttf;base64,) format("truetype")}
:root{--academic:'Latin Modern','Computer Modern',Georgia,serif}
h1{font:700 clamp(36px,4.5vw,58px)/1.15 var(--academic);letter-spacing:-.015em;margin:18px 0 28px}
.masthead{margin-top:48px}
.contents nav a,.contents nav span,.contents .back-top{font-family:var(--academic);font-size:16px}
.contents>p{font:700 18px/1.4 var(--academic);letter-spacing:0;text-transform:none}
figcaption,.hero figcaption{font:15px/1.5 var(--academic);letter-spacing:0}
.measurements{font:16px/1.55 var(--academic)}
.measurements th{font-weight:700}
.equation{overflow-x:auto;max-width:100%;margin:24px 0 30px;padding:4px 2px}
.katex{font-size:1.04em}.katex-display{margin:.5em 0}
@media(max-width:760px){h1{font-size:38px}.contents nav a,.contents nav span{font-size:15px}figcaption{font-size:15px}.hero figcaption{font-size:12px}.measurements{font-size:14px}.equation{font-size:15px}}
@media print{h1{font-size:30pt}figcaption,.hero figcaption{font-size:10pt}.measurements{font-size:10pt}.equation{overflow:visible;break-inside:avoid;font-size:10pt}}

/* Match supporting text to the article; retain the original title face. */
h1{font-family:'EB Garamond',Georgia,serif;font-weight:500}
.contents>p,.contents nav a,.contents nav span,.contents .back-top,
.measurements,figcaption,.hero figcaption{font-family:var(--serif)}

/* Center captions and standalone article figures. */
figcaption{ text-align:center; }
article section > figure{ width:80%; margin-inline:auto; }
